import{_ as e,o,c as d,ag as a}from"./chunks/framework.ePeAWSvT.js";const p=JSON.parse('{"title":"Data Adaptation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/datahub-data-adaptation.md","filePath":"guide/datahub-data-adaptation.md"}'),r={name:"guide/datahub-data-adaptation.md"};function s(n,t,i,c,l,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="data-adaptation" tabindex="-1">Data Adaptation <a class="header-anchor" href="#data-adaptation" aria-label="Permalink to &quot;Data Adaptation&quot;">​</a></h1><p>There are ways to adapt the data being read or written by the <a href="./reference-common-model.html">Common Model</a>. For example, if one system displays data as a decimal number, but you want the data to show as a monetary value, you can transform that data as the Common Model reads and/or writes it. Adapting data is more likely to be done on the subscribing side, but it is possible to execute on both.</p><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>Only available adaptation options will be displayed based on your configured Endpoints and Mapping Actions.</p></div><h2 id="advanced-tab" tabindex="-1">Advanced Tab <a class="header-anchor" href="#advanced-tab" aria-label="Permalink to &quot;Advanced Tab&quot;">​</a></h2><p>In the advanced settings, you can dictate when data gets transferred from the Common Model to other systems. For instance, on the subscribing side, you may want some functionality to only execute when a new record is created or only when data is updated. Also, data taken from the Common Model that is a string, but needs to be written to a Connector as a double or decimal value, changing the output, can be done here.</p><h3 id="read-action" tabindex="-1">Read Action <a class="header-anchor" href="#read-action" aria-label="Permalink to &quot;Read Action&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>FK System Override</strong></td><td>When the data that is read from the Connector creates a Foreign Key on the Data Model, it will by default set the system of Connector. This override allows you to override the key as a value from another system.</td></tr></tbody></table><h3 id="write-action" tabindex="-1">Write Action <a class="header-anchor" href="#write-action" aria-label="Permalink to &quot;Write Action&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>FK System Override</strong></td><td>When the data is written to the Connector, it will by default pull the Foreign Key value of the Connector it is writing to. This override allows you to override the key as a value from another system.</td></tr><tr><td><strong>Supported Operations</strong></td><td>By default, the map will execute for both Create and Updates; however, Supported Operations allows you to direct the map to only execute on a specific Write Operation, Create or Update.</td></tr><tr><td><strong>Value Type</strong></td><td>Converts the mapped value to a given type — numeric, date, etc. This is a <em>conversion</em>, not a display format, and it runs after any transforms on the map. See <a href="./reference-value-formatting.html#order-of-operations">Value Formatting</a>.</td></tr><tr><td><strong>Supported Systems</strong></td><td>By default, the map will execute for any system that posts a message that this Connector receives; however, Supported Systems allow you to only execute this map if the message came from a specific list of systems.</td></tr><tr><td><strong>FK Use Label</strong></td><td>By default, the Foreign Key map writes the value of the Foreign Key; however, this setting allows you to override the default and instead use the Label of the Foreign Key that is stored inside the Central Index.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Users should implement the <strong>Supported Systems</strong> functionality infrequently and only in necessary instances, as this will isolate the data transfer to that specific Mapping.</p></div><h2 id="transforms-tab" tabindex="-1">Transforms Tab <a class="header-anchor" href="#transforms-tab" aria-label="Permalink to &quot;Transforms Tab&quot;">​</a></h2><p>Transforms can be added to either subscribe or publish Mapping; however, they are more commonly used to modify the data being consumed by a system (on the subscribe side). Transforms can be strung together to manipulate data in multiple ways.</p><p>Transforms run <strong>in list order</strong>, and the <strong>Value Type</strong> setting on the Advanced tab is applied <em>after</em> all of them. That ordering matters whenever a transform produces your final wire format — see <a href="./reference-value-formatting.html#order-of-operations">Value Formatting → Order of operations</a>.</p><p>Transforms marked <strong>Recipes</strong> have worked examples under <a href="#transform-recipes">Transform Recipes</a>.</p><table tabindex="0"><thead><tr><th>Transform</th><th>Description</th><th>Inputs</th></tr></thead><tbody><tr><td><strong>Addition</strong></td><td>Adds a value to a property on the Data Model and outputs the result.</td><td>Add -- the value to be added</td></tr><tr><td><strong>Auto-Number for Key</strong></td><td>Generates a unique identifier for each child on a message (starts at 1, 2, and so on).</td><td>None (only used on primary key maps)</td></tr><tr><td><strong>Business Logic Map</strong></td><td>Adds conditional logic to a single property. Within a BizLogicMap, you can add Groups for more complex scenarios, where you can achieve And/Or scenarios, but between groups it supports only Or. For example, if the property value equals X or the property value equals Y, then return Z. Conditions are exact-match only — see the warning in its <a href="#recipes-biz-logic-map">Recipes</a>.</td><td>Group: And/Or, Operator, Value, Return Value. Else Return Value: If all of the groups return false, this value is returned from the map.</td></tr><tr><td><strong>Business Logic Map - Simple</strong></td><td>Adds conditional logic to a single property. This is the same concept as BizLogicMap, but only matches for equality and does not allow for more complex logic with groupings (e.g. if equals this value then return that value). <a href="#recipes-biz-logic-map-simple">Recipes</a></td><td>Comparison: The value you are comparing the property to be equivalent to; then Return: If the value of the property equals the value of the Comparison, then return this value. Return Null, Return Original Value, Else Return Value.</td></tr><tr><td><strong>Compute Expression</strong></td><td>This transform can be used to take in multiple properties and perform conditional logic or computation and return a value. Uses the syntax for <a href="https://learn.microsoft.com/en-us/dotnet/fundamentals/runtime-libraries/system-data-datacolumn-expression" target="_blank" rel="noreferrer">.NET DataTable.Compute</a>. <a href="#recipes-compute-expression">Recipes</a></td><td>Expression</td></tr><tr><td><strong>Convert From Base64</strong></td><td>Used to convert a property from a Base64 encoded string, typically in file upload scenarios.</td><td>None</td></tr><tr><td><strong>Convert TimeZone to UTC</strong></td><td>The inverse of Convert UTC To TimeZone: treats the incoming date/time as local to the chosen time zone and converts it to UTC. Typically used on a publish map when the source system stores local times. Accepts a date/time or a parseable date string.</td><td>Time Zone</td></tr><tr><td><strong>Convert To Base64</strong></td><td>Encodes the value as a Base-64 string (UTF-8).</td><td>None</td></tr><tr><td><strong>Convert UTC To TimeZone</strong></td><td>Used to convert a date time that is in UTC format to a specific time zone, most likely on a subscriber.</td><td>Time Zone</td></tr><tr><td><strong>CSV to List</strong></td><td>A single property that is a character delimited list of values, split into a List. This transform will only work when mapping into values on the Common Model that is a list of strings. <a href="#recipes-lists">Recipes</a></td><td>Make Distinct, Trim Items, Character Separator</td></tr><tr><td><strong>Date Change</strong></td><td>Shifts a date/time by a fixed offset. Each unit is added independently and may be negative, so &quot;-1 day, +2 hours&quot; is a single transform. Useful for overlap windows on a read filter, or for aligning to a system that expects an inclusive end date. <a href="#recipes-date-change">Recipes</a></td><td>Total Seconds, Total Minutes, Total Hours, Total Days, Total Months, Total Years</td></tr><tr><td><strong>Date Only</strong></td><td>Strips the time component, leaving midnight of the same date. Accepts a date/time or a parseable date string, so it doubles as a way to coerce a date string into a real date before a <a href="./reference-value-formatting.html#typed-values">Formatting Template</a>.</td><td>None</td></tr><tr><td><strong>Default To Current Date</strong></td><td>If the incoming property value is null, it will default to UTC date/time. Typically used on saves for a create record.</td><td>None</td></tr><tr><td><strong>Default Value</strong></td><td>If the incoming property value is null or empty, it will default to this value. Typically used on saves for a create record. <a href="#recipes-default-value">Recipes</a></td><td>A predetermined value</td></tr><tr><td><strong>Division</strong></td><td>Takes a property on the Data Model and divides by a value; then, outputs the result.</td><td>A Divisor (the value of what you are dividing by)</td></tr><tr><td><strong>Flatten Date/Time</strong></td><td>Used to break a date apart into individual properties on a Save, or to combine them on a Read. For example: <code>{ &quot;year&quot;: 2023, &quot;month&quot;: 1, &quot;day&quot;: 1 }</code></td><td>Include Time, Protocol, Year, Month, Day</td></tr><tr><td><strong>Formatting Template</strong></td><td>Takes one to many properties on the Data Model and does a string format; then, returns the result. The format of the template uses placeholders like <code>{0}-{1}-{2}</code>. The mapping engine replaces <code>{0}</code> with the value of the first property, and so on. Each placeholder can carry a format — <code>{0:yyyy-MM-dd}</code>, <code>{0:D6}</code>. See <a href="./reference-value-formatting.html">Value Formatting</a>. <a href="#recipes-formatting-template">Recipes</a></td><td>Template</td></tr><tr><td><strong>From Epoch Time</strong></td><td>Converts a Unix epoch timestamp in <strong>milliseconds</strong> into a UTC date/time. Pair with a Formatting Template to render it in the shape the target expects.</td><td>None</td></tr><tr><td><strong>Invoke Instance Method</strong> <em>(Deprecated)</em></td><td>Calls a named method on the incoming value by reflection. <strong>Deprecated</strong> — see the warning below.</td><td>Method Name, Parameters (type + value)</td></tr><tr><td><strong>Invoke Static Method</strong> <em>(Deprecated)</em></td><td>Calls a named static method on a named .NET class by reflection, passing the incoming value as the argument. <strong>Deprecated</strong> — see the warning below.</td><td>Class Name, Method Name, Parameter Types</td></tr><tr><td><strong>Invoke Static Property</strong></td><td>Returns the value of a named static property or field on a named .NET class. Ignores the incoming value.</td><td>Class Name, Property Name</td></tr><tr><td><strong>JSON Contains</strong></td><td>Executes a JSONPath. If it finds a value, it returns <em>true</em>, else returns <em>false</em>. <a href="#recipes-json-contains">Recipes</a></td><td>JSONPath</td></tr><tr><td><strong>Math Truncate</strong></td><td>Trims off all decimal values.</td><td>None</td></tr><tr><td><strong>Multiplication</strong></td><td>Multiplies a value to a property on the Data Model and outputs the result.</td><td>Multiplier (the value to be multiplied)</td></tr><tr><td><strong>Parse to JSON</strong></td><td>Takes a string value and generates a JSON object.</td><td>None</td></tr><tr><td><strong>Regex Match</strong></td><td>Pulls a value out of a string based on a pattern — for example, the month out of a date string, or an order number out of a description. Returns the <strong>first capture group</strong> <code>( )</code> of the match, not the whole match, and null when nothing matches. <a href="#recipes-regex-match">Recipes</a></td><td>Match Pattern</td></tr><tr><td><strong>Regex Replace</strong></td><td>Finds text matching a pattern and replaces it — reformatting (10 digits into a phone number), cleaning (stripping non-digits, collapsing spaces), or reordering parts of a value. A value that doesn&#39;t match passes through unchanged. <a href="#recipes-regex-replace">Recipes</a></td><td>Match Pattern: tells it what to find in the string. Replace Pattern: tells it how to reformat the string based on what has matched.</td></tr><tr><td><strong>Round</strong></td><td>Applies rounding on a numeric property. <a href="#recipes-round">Recipes</a></td><td>Behavior: Always round up, Always round down, Default. Precision.</td></tr><tr><td><strong>String Join</strong></td><td>Takes multiple values from a Publisher and writes them as a single, delimited string to the Subscriber. <a href="#recipes-lists">Recipes</a></td><td>Delimiter</td></tr><tr><td><strong>Substring</strong></td><td>Retrieves a portion of a string. For example, if a field can only accept 30 characters, Substring can be used to return only the first 30 characters of a property and remove the rest.</td><td>Starting Index: the position on the string you want to start with (e.g. the starting position is 0). Number of Characters. <a href="#recipes-substring">Recipes</a></td></tr><tr><td><strong>Subtraction</strong></td><td>Subtracts a value from a property on the Data Model and outputs the result.</td><td>Subtract -- the value being subtracted</td></tr><tr><td><strong>To Epoch Time</strong></td><td>Converts a date/time (or a parseable date string) into a Unix epoch timestamp in <strong>milliseconds</strong>.</td><td>None</td></tr><tr><td><strong>To Lowercase</strong></td><td>Lowercases the value. String input only — a non-string value raises an error, so place it after any transform that produces text.</td><td>None</td></tr><tr><td><strong>To Title Case</strong></td><td>Title-cases the value (e.g. <code>acme holdings</code> → <code>Acme Holdings</code>). String input only.</td><td>None</td></tr><tr><td><strong>To Uppercase</strong></td><td>Uppercases the value. String input only.</td><td>None</td></tr><tr><td><strong>US State Abbreviation</strong></td><td>Converts between US state names and their two-letter abbreviations, in either direction. Covers the 50 states, DC, and the USPS territories. Matching is case-insensitive; abbreviations come back uppercase and names in canonical casing.</td><td>Mode: Abbreviation → Full Name, or Full Name → Abbreviation. Return Original Value (default) or Else Return Value, used when no match is found.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Invoke Instance Method</strong> and <strong>Invoke Static Method</strong> are deprecated. They allow arbitrary .NET methods to be invoked from configuration and will be removed in a future release. Use a Compute Expression, a Business Logic Map, or a purpose-built transform instead.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Several of these transforms are the answer to &quot;my format specifier isn&#39;t doing anything&quot; — <strong>Date Only</strong>, <strong>Convert TimeZone to UTC</strong>, and <strong>From Epoch Time</strong> all coerce text or a number into a real date, which a <a href="./reference-value-formatting.html#dates">Formatting Template</a> can then format. See <a href="./reference-value-formatting.html#typed-values">Value Formatting</a>.</p></div><h2 id="transform-recipes" tabindex="-1">Transform Recipes <a class="header-anchor" href="#transform-recipes" aria-label="Permalink to &quot;Transform Recipes {#transform-recipes}&quot;">​</a></h2><p>Worked examples for the transforms that take configuration. Each section below opens with how the transform behaves at the edges — what happens on no match, on a null, on the wrong type — followed by recipes you can copy. Every input → output pair shown was produced by the transform itself.</p><div class="tip custom-block"><p class="custom-block-title">Leading and trailing spaces are trimmed</p><p>Transform fields drop leading and trailing whitespace when you leave them. A Delimiter of <code>, </code> is saved as <code>,</code>, and a Replace Pattern can&#39;t be a lone space. Spaces <em>inside</em> a value are kept. In a regex, write <code>\\s</code> or <code>[ ]</code> where you need a space at either end.</p></div><h3 id="recipes-regex-replace" tabindex="-1">Regex Replace <a class="header-anchor" href="#recipes-regex-replace" aria-label="Permalink to &quot;Regex Replace {#recipes-regex-replace}&quot;">​</a></h3><p>Uses <a href="https://learn.microsoft.com/en-us/dotnet/standard/base-types/regular-expression-language-quick-reference" target="_blank" rel="noreferrer">.NET regular expressions</a>. <strong>Match Pattern</strong> finds the text, and <strong>Replace Pattern</strong> says what to put in its place.</p><ul><li><strong>Every match is replaced</strong>, not just the first. Anchor with <code>^</code> and <code>$</code> when the pattern should describe the whole value.</li><li><strong>No match → the value passes through unchanged</strong>, type included. A match always produces text.</li><li><strong>In Replace Pattern</strong>, <code>$1</code>, <code>$2</code>… insert what each <code>( )</code> group captured. Use <code>${1}</code> when a digit follows (<code>${1}0</code>), and <code>$$</code> for a literal <code>$</code>. Leave it <strong>blank</strong> to delete the match.</li><li><strong>Case-sensitive by default.</strong> Start the pattern with <code>(?i)</code> to ignore case.</li><li><strong>Escape regex characters you mean literally</strong>: <code>.</code> matches <em>any</em> character, so <code>\\.</code> is a period. The same goes for <code>( ) [ ] + * ? | ^ $ \\</code>.</li><li><strong>Non-text values are converted to text first.</strong> A date becomes culture-dependent text like <code>3/9/2026 2:05:07 PM</code>, so put a <a href="#recipes-formatting-template">Formatting Template</a> ahead of it to control that text.</li></ul><details class="details custom-block"><summary>Recipes</summary><table tabindex="0"><thead><tr><th>Goal</th><th>Match Pattern</th><th>Replace Pattern</th><th>Input</th><th>Output</th></tr></thead><tbody><tr><td>Format a 10-digit phone number, whatever punctuation it arrives with</td><td><code>^\\D*(\\d{3})\\D*(\\d{3})\\D*(\\d{4})\\D*$</code></td><td><code>($1) $2-$3</code></td><td><code>555.123.4567</code></td><td><code>(555) 123-4567</code></td></tr><tr><td>Strip everything except digits</td><td><code>\\D</code></td><td><em>(blank)</em></td><td><code>(555) 123-4567</code></td><td><code>5551234567</code></td></tr><tr><td>Insert dashes into a fixed-length ID</td><td><code>^(\\d{3})(\\d{2})(\\d{4})$</code></td><td><code>$1-$2-$3</code></td><td><code>123456789</code></td><td><code>123-45-6789</code></td></tr><tr><td>Remove leading zeros (but keep a lone <code>0</code>)</td><td><code>^0+(?=\\d)</code></td><td><em>(blank)</em></td><td><code>000123</code></td><td><code>123</code></td></tr><tr><td>Reorder date text from <code>MM/dd/yyyy</code> to <code>yyyy-MM-dd</code></td><td><code>^(\\d{2})/(\\d{2})/(\\d{4})$</code></td><td><code>$3-$1-$2</code></td><td><code>03/09/2026</code></td><td><code>2026-03-09</code></td></tr><tr><td>&quot;Last, First&quot; → &quot;First Last&quot;</td><td><code>^\\s*([^,]+?)\\s*,\\s*(.+?)\\s*$</code></td><td><code>$2 $1</code></td><td><code>Doe, John</code></td><td><code>John Doe</code></td></tr><tr><td>Strip a fixed prefix</td><td><code>^INV-</code></td><td><em>(blank)</em></td><td><code>INV-1042</code></td><td><code>1042</code></td></tr><tr><td>Collapse runs of spaces to one</td><td><code>\\s+(?=\\s)</code></td><td><em>(blank)</em></td><td><code>Acme Holdings LLC</code></td><td><code>Acme Holdings LLC</code></td></tr><tr><td>Trim surrounding whitespace</td><td><code>^\\s+|\\s+$</code></td><td><em>(blank)</em></td><td><code>␣␣Acme␣␣</code></td><td><code>Acme</code></td></tr><tr><td>Mask all but the last four digits</td><td><code>\\d(?=\\d{4})</code></td><td><code>*</code></td><td><code>4111111111111111</code></td><td><code>************1111</code></td></tr><tr><td>Normalize a suffix, ignoring case</td><td><code>(?i)\\binc\\.?$</code></td><td><code>Inc.</code></td><td><code>Acme INC</code></td><td><code>Acme Inc.</code></td></tr><tr><td>Add a currency symbol</td><td><code>^(\\d+\\.\\d{2})$</code></td><td><code>$$$1</code></td><td><code>19.99</code></td><td><code>$19.99</code></td></tr><tr><td>Blank out placeholder values</td><td><code>(?i)^\\s*(n/?a|null|none|-)\\s*$</code></td><td><em>(blank)</em></td><td><code>N/A</code></td><td><em>(empty)</em></td></tr></tbody></table></details><details class="details custom-block"><summary>Chaining: replace a placeholder with a real default</summary><p>Source systems often send <code>N/A</code>, <code>none</code>, or <code>-</code> where they mean &quot;no value&quot;. Two transforms in order:</p><ol><li><strong>Regex Replace</strong> — Match <code>(?i)^\\s*(n/?a|null|none|-)\\s*$</code>, Replace <em>(blank)</em>. <code>N/A</code> becomes empty; <code>Nathan</code> doesn&#39;t match and passes through.</li><li><strong>Default Value</strong> — Value <code>Unknown</code>. Fires on null <strong>or empty</strong>, so the blanked placeholder becomes <code>Unknown</code>.</li></ol></details><h3 id="recipes-regex-match" tabindex="-1">Regex Match <a class="header-anchor" href="#recipes-regex-match" aria-label="Permalink to &quot;Regex Match {#recipes-regex-match}&quot;">​</a></h3><p>Extracts part of a value. The thing to remember: <strong>it returns the first capture group <code>( )</code>, not the whole match.</strong></p><ul><li><strong>Wrap what you want to keep in parentheses.</strong> A pattern with no group returns an empty string, even when it matches. To return the entire match, wrap the whole pattern: <code>(\\d+)</code>.</li><li><strong>Use <code>(?:…)</code> to group without capturing</strong>, so alternatives don&#39;t steal group 1 — see the PO recipe below.</li><li><strong>No match → null</strong>, unlike Regex Replace, which passes the value through. Follow with <strong>Default Value</strong> if you need a fallback.</li><li><strong>A full ISO timestamp read from JSON arrives as a date, not text</strong>, so text patterns like the month recipe below won&#39;t match it. Use a Formatting Template such as <code>{0:MM}</code> instead. A date-only string like <code>2026-03-09</code> stays text.</li></ul><details class="details custom-block"><summary>Recipes</summary><table tabindex="0"><thead><tr><th>Goal</th><th>Match Pattern</th><th>Input</th><th>Output</th></tr></thead><tbody><tr><td>Number after a <code>#</code></td><td><code>#(\\d+)</code></td><td><code>Order #12345 shipped</code></td><td><code>12345</code></td></tr><tr><td>Domain from an email address</td><td><code>@(.+)$</code></td><td><code>jane@acme.com</code></td><td><code>acme.com</code></td></tr><tr><td>Month from an ISO date string</td><td><code>^\\d{4}-(\\d{2})</code></td><td><code>2026-03-09</code></td><td><code>03</code></td></tr><tr><td>Last four characters</td><td><code>(.{4})$</code></td><td><code>4111111111111111</code></td><td><code>1111</code></td></tr><tr><td>First word</td><td><code>^\\s*(\\S+)</code></td><td><code>␣␣Jane Q Public</code></td><td><code>Jane</code></td></tr><tr><td>Last word</td><td><code>(\\S+)\\s*$</code></td><td><code>Jane Q Public</code></td><td><code>Public</code></td></tr><tr><td>A reference that may follow either of two labels</td><td><code>(?:PO|Purchase Order)\\s*#?\\s*([\\w-]+)</code></td><td><code>Purchase Order # A-77</code></td><td><code>A-77</code></td></tr><tr><td>⚠ No capture group</td><td><code>\\d+</code></td><td><code>Order 12345</code></td><td><em>(empty)</em></td></tr><tr><td>✓ Same, with a group</td><td><code>(\\d+)</code></td><td><code>Order 12345</code></td><td><code>12345</code></td></tr></tbody></table></details><h3 id="recipes-formatting-template" tabindex="-1">Formatting Template <a class="header-anchor" href="#recipes-formatting-template" aria-label="Permalink to &quot;Formatting Template {#recipes-formatting-template}&quot;">​</a></h3><p>Builds a string from one or more values with .NET composite formatting. <a href="./reference-value-formatting.html">Value Formatting</a> is the full reference for format specifiers. The most important rule from it: <strong>a specifier like <code>:D6</code> or <code>:yyyy-MM-dd</code> only applies to a real number or date — text passes through unformatted.</strong></p><ul><li>On a <strong>multi-property map</strong>, the inner maps arrive as <code>{0}</code>, <code>{1}</code>, <code>{2}</code> in the order listed.</li><li>A <strong>null or empty input</strong> is returned unchanged rather than rendered. A null <em>inside</em> a multi-property map renders as empty.</li></ul><details class="details custom-block"><summary>Recipes</summary><table tabindex="0"><thead><tr><th>Goal</th><th>Template</th><th>Input</th><th>Output</th></tr></thead><tbody><tr><td>Full name from two properties (multi-property map)</td><td><code>{0} {1}</code></td><td><code>John</code>, <code>Doe</code></td><td><code>John Doe</code></td></tr><tr><td>One-line address (multi-property map)</td><td><code>{0}, {1}, {2} {3}</code></td><td><code>Columbus</code>, <code>OH</code>, <code>43215</code>, <code>US</code></td><td><code>Columbus, OH, 43215 US</code></td></tr><tr><td>Zero-padded document number</td><td><code>INV-{0:D6}</code></td><td><code>42</code> (a number)</td><td><code>INV-000042</code></td></tr><tr><td>⚠ Same, but the value is text</td><td><code>INV-{0:D6}</code></td><td><code>&quot;42&quot;</code> (text)</td><td><code>INV-42</code></td></tr><tr><td>Date in the target&#39;s format</td><td><code>{0:yyyy-MM-dd}</code></td><td>a date</td><td><code>2026-03-09</code></td></tr></tbody></table></details><details class="details custom-block"><summary>Chaining: format a value that arrives as text</summary><p>When the specifier is ignored because the value is text, convert it first:</p><ul><li><strong>Number as text</strong> → <strong>Compute Expression</strong> <code>Convert(&#39;{0}&#39;, &#39;System.Int32&#39;)</code> → <strong>Formatting Template</strong> <code>INV-{0:D6}</code>. <code>&quot;42&quot;</code> becomes <code>INV-000042</code>.</li><li><strong>Epoch milliseconds</strong> → <strong>From Epoch Time</strong> → <strong>Formatting Template</strong> <code>{0:yyyy-MM-dd}</code>.</li><li><strong>Date string</strong> → <strong>Date Only</strong> (or <strong>Convert TimeZone to UTC</strong>) → <strong>Formatting Template</strong>.</li></ul><p>More in <a href="./reference-value-formatting.html#typed-values">Value Formatting → When the value is text</a>.</p></details><h3 id="recipes-compute-expression" tabindex="-1">Compute Expression <a class="header-anchor" href="#recipes-compute-expression" aria-label="Permalink to &quot;Compute Expression {#recipes-compute-expression}&quot;">​</a></h3><p>Evaluates an <a href="https://learn.microsoft.com/en-us/dotnet/fundamentals/runtime-libraries/system-data-datacolumn-expression" target="_blank" rel="noreferrer">expression</a> after substituting each value into <code>{0}</code>, <code>{1}</code>, … as text. On a multi-property map, the inner maps fill the placeholders in order.</p><ul><li><strong>Text values must be quoted in the expression</strong>: write <code>&#39;{0}&#39;</code>, not <code>{0}</code>. Unquoted text is read as a column name and fails with <em>Cannot find column</em>. Single quotes inside the value are escaped for you, so <code>O&#39;Brien</code> is safe.</li><li><strong>Numbers and booleans are left unquoted</strong>: <code>{0} * 2</code>, <code>IIF({0}, &#39;Yes&#39;, &#39;No&#39;)</code>.</li><li><strong>A null becomes the word <code>null</code></strong>. Unquoted, that is a real null, so <code>IsNull({0}, 0)</code> works. Inside quotes it becomes the text <code>&#39;null&#39;</code>.</li><li><strong>Division is never integer division</strong>: <code>7 / 2</code> is <code>3.5</code>.</li><li><strong><code>Substring</code> here counts from 1</strong>, unlike the Substring transform, which counts from 0.</li><li>Other useful functions: <code>IIF</code>, <code>IsNull</code>, <code>Len</code>, <code>Trim</code>, <code>Convert</code>, <code>LIKE</code> (wildcards <code>*</code> or <code>%</code>), and <code>IN (…)</code>.</li></ul><details class="details custom-block"><summary>Recipes</summary><table tabindex="0"><thead><tr><th>Goal</th><th>Expression</th><th>Input</th><th>Output</th></tr></thead><tbody><tr><td>Line total (multi-property: quantity, unit price)</td><td><code>{0} * {1}</code></td><td><code>3</code>, <code>19.99</code></td><td><code>59.97</code></td></tr><tr><td>Sum two values where either may be null</td><td><code>IsNull({0}, 0) + IsNull({1}, 0)</code></td><td><code>5</code>, null</td><td><code>5</code></td></tr><tr><td>Label by sign</td><td><code>IIF({0} &lt; 0, &#39;Credit&#39;, &#39;Debit&#39;)</code></td><td><code>-12.5</code></td><td><code>Credit</code></td></tr><tr><td>Text to a flag</td><td><code>IIF(&#39;{0}&#39; = &#39;Active&#39;, 1, 0)</code></td><td><code>Active</code></td><td><code>1</code></td></tr><tr><td>Bucket by a list of values</td><td><code>IIF(&#39;{0}&#39; IN (&#39;CA&#39;,&#39;OR&#39;,&#39;WA&#39;), &#39;West&#39;, &#39;Other&#39;)</code></td><td><code>OR</code></td><td><code>West</code></td></tr><tr><td>Prefix test</td><td><code>IIF(&#39;{0}&#39; LIKE &#39;TEST*&#39;, &#39;Y&#39;, &#39;N&#39;)</code></td><td><code>TEST-001</code></td><td><code>Y</code></td></tr><tr><td>Two conditions across two properties</td><td><code>IIF({0} &gt; 100 AND &#39;{1}&#39; = &#39;US&#39;, &#39;Domestic-Large&#39;, &#39;Other&#39;)</code></td><td><code>150</code>, <code>US</code></td><td><code>Domestic-Large</code></td></tr><tr><td>Boolean to Yes/No</td><td><code>IIF({0}, &#39;Yes&#39;, &#39;No&#39;)</code></td><td><code>true</code></td><td><code>Yes</code></td></tr><tr><td>Concatenate text</td><td><code>&#39;{0}&#39; + &#39; &#39; + &#39;{1}&#39;</code></td><td><code>John</code>, <code>Doe</code></td><td><code>John Doe</code></td></tr><tr><td>Text to a number</td><td><code>Convert(&#39;{0}&#39;, &#39;System.Int32&#39;)</code></td><td><code>&quot;41&quot;</code></td><td><code>41</code></td></tr><tr><td>First three characters (1-based)</td><td><code>Substring(&#39;{0}&#39;, 1, 3)</code></td><td><code>ABCDEF</code></td><td><code>ABC</code></td></tr></tbody></table></details><h3 id="recipes-biz-logic-map-simple" tabindex="-1">Business Logic Map - Simple <a class="header-anchor" href="#recipes-biz-logic-map-simple" aria-label="Permalink to &quot;Business Logic Map - Simple {#recipes-biz-logic-map-simple}&quot;">​</a></h3><p>A lookup table: if the value equals a <strong>Comparison</strong>, return its <strong>Return</strong>.</p><ul><li><strong>Matching is exact and case-sensitive</strong> against the value as text: <code>A</code> does not match <code>a</code>. A boolean compares as <code>True</code> or <code>False</code>, capitalized.</li><li><strong>No match</strong> returns <strong>Else Return Value</strong>, or the value itself when <strong>Return Original Value</strong> is on. A null input never matches a Comparison and goes to the else branch.</li><li>The same Comparison can&#39;t be listed twice; the save is rejected.</li></ul><details class="details custom-block"><summary>Recipes</summary><table tabindex="0"><thead><tr><th>Goal</th><th>Configuration</th><th>Input → Output</th></tr></thead><tbody><tr><td>Translate codes to labels, with a catch-all</td><td><code>A</code> → <code>Active</code>, <code>I</code> → <code>Inactive</code>; Else Return Value <code>Unknown</code></td><td><code>A</code> → <code>Active</code>, <code>X</code> → <code>Unknown</code>, <code>a</code> → <code>Unknown</code></td></tr><tr><td>Override a few values and pass the rest through</td><td><code>Cancelled</code> → <code>Void</code>; <strong>Return Original Value</strong> on</td><td><code>Cancelled</code> → <code>Void</code>, <code>Open</code> → <code>Open</code></td></tr><tr><td>Boolean to <code>Y</code>/<code>N</code></td><td><code>True</code> → <code>Y</code>, <code>False</code> → <code>N</code></td><td><code>true</code> → <code>Y</code></td></tr></tbody></table></details><h3 id="recipes-biz-logic-map" tabindex="-1">Business Logic Map <a class="header-anchor" href="#recipes-biz-logic-map" aria-label="Permalink to &quot;Business Logic Map {#recipes-biz-logic-map}&quot;">​</a></h3><p>Groups of conditions, each with a <strong>Return Value</strong>. Groups are checked in order and the first group that is true wins. Within a group, <code>And</code> binds tighter than <code>Or</code>. If no group is true, <strong>Else Return Value</strong> is returned.</p><div class="warning custom-block"><p class="custom-block-title">Conditions are equality-only</p><p>The <strong>Operator</strong> on each condition is not currently evaluated. Every condition is an exact, case-sensitive equality test, whatever operator is selected. And because every condition tests the <em>same</em> value, <code>And</code> between two different values can never be true. In practice this transform maps <strong>several values to one result</strong>. Anything richer — not-equals, greater-than, contains — belongs in a <a href="#recipes-compute-expression">Compute Expression</a>.</p></div><details class="details custom-block"><summary>Recipe: collapse many statuses into a few</summary><table tabindex="0"><thead><tr><th>Group</th><th>Conditions</th><th>Return Value</th></tr></thead><tbody><tr><td>1</td><td><code>New</code> Or <code>Pending</code> Or <code>In Progress</code></td><td><code>Open</code></td></tr><tr><td>2</td><td><code>Done</code> Or <code>Cancelled</code></td><td><code>Closed</code></td></tr><tr><td>Else</td><td></td><td><code>Other</code></td></tr></tbody></table><p><code>In Progress</code> → <code>Open</code>, <code>Cancelled</code> → <code>Closed</code>, <code>On Hold</code> → <code>Other</code>.</p></details><h3 id="recipes-substring" tabindex="-1">Substring <a class="header-anchor" href="#recipes-substring" aria-label="Permalink to &quot;Substring {#recipes-substring}&quot;">​</a></h3><ul><li><strong>Starting Index counts from 0.</strong></li><li><strong>Number of Characters must be set</strong>: at <code>0</code> the result is empty. A value shorter than requested returns whatever is there.</li><li><strong>A Starting Index past the end of the value raises an error.</strong> If values can be shorter than your prefix, use Regex Replace instead.</li><li>It can&#39;t count from the end. For the last <em>N</em> characters, use Regex Match <code>(.{N})$</code>.</li></ul><details class="details custom-block"><summary>Recipes</summary><table tabindex="0"><thead><tr><th>Goal</th><th>Starting Index</th><th>Number of Characters</th><th>Input</th><th>Output</th></tr></thead><tbody><tr><td>Truncate to a field&#39;s max length</td><td><code>0</code></td><td><code>30</code></td><td><code>Hi</code></td><td><code>Hi</code></td></tr><tr><td>First five characters</td><td><code>0</code></td><td><code>5</code></td><td><code>Hello world</code></td><td><code>Hello</code></td></tr><tr><td>Drop a fixed 4-character prefix</td><td><code>4</code></td><td><code>1000</code></td><td><code>INV-1042</code></td><td><code>1042</code></td></tr></tbody></table></details><h3 id="recipes-round" tabindex="-1">Round <a class="header-anchor" href="#recipes-round" aria-label="Permalink to &quot;Round {#recipes-round}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rounding Behavior</th><th>Rule</th><th><code>2.345</code> (Precision 2)</th><th><code>-2.349</code> (Precision 2)</th></tr></thead><tbody><tr><td><strong>Default</strong></td><td>Nearest, halves away from zero</td><td><code>2.35</code></td><td><code>-2.35</code></td></tr><tr><td><strong>Always Round Up</strong></td><td>Toward positive infinity (ceiling)</td><td><code>2.35</code></td><td><code>-2.34</code></td></tr><tr><td><strong>Always Round Down</strong></td><td>Toward zero (truncate)</td><td><code>2.34</code></td><td><code>-2.34</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Whole numbers read from JSON</p><p>Round accepts decimals, doubles, 32-bit integers, and numeric text. A whole number read from a JSON payload (<code>42</code>, not <code>42.0</code>) arrives as a 64-bit integer and raises <em>Invalid input type</em>. That includes a field that is usually fractional but sometimes whole, like <code>2.5</code> one record and <code>3</code> the next.</p></div><details class="details custom-block"><summary>Keeping trailing zeros</summary><p>The result is a plain number, so trailing zeros are dropped: <code>2.50</code> comes out as <code>2.5</code>. When the target needs a fixed number of decimals, follow Round with a <strong>Formatting Template</strong> <code>{0:0.00}</code>.</p></details><h3 id="recipes-date-change" tabindex="-1">Date Change <a class="header-anchor" href="#recipes-date-change" aria-label="Permalink to &quot;Date Change {#recipes-date-change}&quot;">​</a></h3><p>Each unit is added independently, and any unit can be negative. Months and years respect calendar length: Jan 31 + 1 month is Feb 28.</p><details class="details custom-block"><summary>Recipes</summary><table tabindex="0"><thead><tr><th>Goal</th><th>Chain</th><th>Input</th><th>Output</th></tr></thead><tbody><tr><td>Overlap window — reach one day further back</td><td><strong>Date Change</strong> Days <code>-1</code></td><td><code>2026-03-09 14:05:07</code></td><td><code>2026-03-08 14:05:07</code></td></tr><tr><td>Inclusive end-of-day</td><td><strong>Date Only</strong> → <strong>Date Change</strong> Days <code>1</code>, Seconds <code>-1</code></td><td><code>2026-03-09 14:05:07</code></td><td><code>2026-03-09 23:59:59</code></td></tr></tbody></table></details><h3 id="recipes-lists" tabindex="-1">CSV to List and String Join <a class="header-anchor" href="#recipes-lists" aria-label="Permalink to &quot;CSV to List and String Join {#recipes-lists}&quot;">​</a></h3><p>Inverses of each other: <strong>CSV to List</strong> splits one delimited string into a list, and <strong>String Join</strong> joins a list into one string.</p><ul><li>CSV to List always drops empty entries. A new transform starts with <strong>Trim Items</strong> on and <strong>Make Distinct</strong> off.</li><li>String Join also accepts a JSON array that arrives as text, e.g. <code>[&quot;a&quot;,&quot;b&quot;]</code>.</li></ul><details class="details custom-block"><summary>Recipes</summary><table tabindex="0"><thead><tr><th>Goal</th><th>Configuration</th><th>Input</th><th>Output</th></tr></thead><tbody><tr><td>Split a messy semicolon list</td><td>CSV to List, Separator <code>;</code></td><td><code>red; blue;;red␣</code></td><td><code>[&quot;red&quot;, &quot;blue&quot;, &quot;red&quot;]</code></td></tr><tr><td>Same, without duplicates</td><td>CSV to List, Separator <code>;</code>, Make Distinct on</td><td><code>red; blue;;red␣</code></td><td><code>[&quot;red&quot;, &quot;blue&quot;]</code></td></tr><tr><td>Join a list for a single text field</td><td>String Join, Delimiter <code>|</code></td><td><code>[&quot;a&quot;, &quot;b&quot;, &quot;c&quot;]</code></td><td><code>a|b|c</code></td></tr></tbody></table></details><h3 id="recipes-default-value" tabindex="-1">Default Value <a class="header-anchor" href="#recipes-default-value" aria-label="Permalink to &quot;Default Value {#recipes-default-value}&quot;">​</a></h3><p>Fires when the value is <strong>null or empty</strong>. A value of only spaces is <em>not</em> empty and passes through, so put a trim — Regex Replace <code>^\\s+|\\s+$</code> → <em>(blank)</em> — ahead of it if that matters. See also <a href="#recipes-regex-replace">replacing placeholder values</a> such as <code>N/A</code>.</p><h3 id="recipes-json-contains" tabindex="-1">JSON Contains <a class="header-anchor" href="#recipes-json-contains" aria-label="Permalink to &quot;JSON Contains {#recipes-json-contains}&quot;">​</a></h3><p>Returns <code>true</code> if the <a href="https://www.newtonsoft.com/json/help/html/QueryJsonSelectTokenJsonPath.htm" target="_blank" rel="noreferrer">JSONPath</a> selects anything, otherwise <code>false</code>.</p><ul><li><strong>The input must be a JSON object or array.</strong> JSON that arrives as <em>text</em> always returns <code>false</code>, so put <strong>Parse to JSON</strong> ahead of it.</li><li>An empty array selects nothing, so <code>$.tags[*]</code> doubles as a &quot;has any items&quot; test.</li></ul><details class="details custom-block"><summary>Recipes</summary><p>Against <code>{ &quot;lines&quot;: [ { &quot;type&quot;: &quot;Freight&quot;, &quot;amt&quot;: 10 }, { &quot;type&quot;: &quot;Item&quot;, &quot;amt&quot;: 5 } ], &quot;tags&quot;: [] }</code>:</p><table tabindex="0"><thead><tr><th>Goal</th><th>JSONPath</th><th>Output</th></tr></thead><tbody><tr><td>Has a freight line?</td><td><code>$.lines[?(@.type == &#39;Freight&#39;)]</code></td><td><code>true</code></td></tr><tr><td>Has a discount line?</td><td><code>$.lines[?(@.type == &#39;Discount&#39;)]</code></td><td><code>false</code></td></tr><tr><td>Any line over 8?</td><td><code>$.lines[?(@.amt &gt; 8)]</code></td><td><code>true</code></td></tr><tr><td>Any tags at all?</td><td><code>$.tags[*]</code></td><td><code>false</code></td></tr></tbody></table></details><h2 id="behaviors-tab" tabindex="-1">Behaviors Tab <a class="header-anchor" href="#behaviors-tab" aria-label="Permalink to &quot;Behaviors Tab&quot;">​</a></h2><p>Behaviors are advanced level options to assist developers in further isolating data transfers. They are unique overrides, used to adapt the data so that it behaves differently than it typically would.</p><table tabindex="0"><thead><tr><th>Behavior</th><th>Description</th></tr></thead><tbody><tr><td><strong>Allow Empty Fixed Value</strong></td><td>Used primarily on Write Maps, it sets empty string on a field that we do not have mapped, but that needs to be included on the payload of a Save.</td></tr><tr><td><strong>Bi-Directional Blocking Identifier</strong></td><td>Used to select a field separate from the key that is unique and can be used to enforce bi-directional blocking on bi-directional endpoints.</td></tr><tr><td><strong>Hide From Logging</strong></td><td>Used to hide sensitive data (SSN, salaries, etc.) from the logs.</td></tr><tr><td><strong>Allow Primary Key to Change</strong></td><td>Used primarily on Read Maps to tell the engine it can update a value on a Primary Key in the Central Index. By default, Central prevents this from happening, so this acts as an override.</td></tr><tr><td><strong>Map from Absolute Root</strong></td><td>Used primarily on Read Maps, and mainly inside of nested maps, to path to the top level.</td></tr><tr><td><strong>Map To Absolute Root</strong></td><td>Used in nested lists to retrieve a value from the parent.</td></tr><tr><td><strong>Skip if Null</strong></td><td>Used primarily on Write maps, in instances where you want to ignore the map entirely if the incoming value on the property is null.</td></tr></tbody></table><h2 id="overrides" tabindex="-1">Overrides <a class="header-anchor" href="#overrides" aria-label="Permalink to &quot;Overrides&quot;">​</a></h2><p>Overrides allow you to define different connector properties based on operations (Create vs Update). For example, you may want a different mapping behavior on creating a new record vs. updating an existing record.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./datahub-action-mapping.html">Action Mapping</a> — Map endpoint actions to the Common Model</li><li><a href="./datahub-endpoint-config.html">Endpoint Configuration</a> — Configure endpoint action inputs and parameterization</li><li><a href="./datahub-endpoint-settings.html">Endpoint Settings</a> — Configure processing behavior for endpoints</li><li><a href="./session-values.html">Session Values</a> — Extract and reuse values across multi-step API workflows</li><li><a href="./reference-value-formatting.html">Value Formatting</a> — Format strings for placeholders and templates, with common examples</li></ul>',73)])])}const m=e(r,[["render",s]]);export{p as __pageData,m as default};
